'use strict';

const assert = require('assert');
const nconf = require('nconf');

const db = require('./mocks/databasemock');

const plugins = require('../src/plugins');
const categories = require('../src/categories');
const topics = require('../src/topics');
const posts = require('../src/posts');
const meta = require('../src/meta');
const user = require('../src/user');

describe('Topic Events', () => {
	let fooUid;
	let topic;
	before(async () => {
		fooUid = await user.create({ username: 'foo', password: '123456' });

		const categoryObj = await categories.create({
			name: 'Test Category',
			description: 'Test category created by testing script',
		});
		topic = await topics.post({
			title: 'topic events testing',
			content: 'foobar one two three',
			uid: fooUid,
			cid: 1,
		});
	});

	describe('.init()', () => {
		before(() => {
			topics.events._ready = false;
		});

		it('should allow a plugin to expose new event types', async () => {
			await plugins.hooks.register('core', {
				hook: 'filter:topicEvents.init',
				method: async ({ types }) => {
					types.foo = {
						icon: 'bar',
						text: 'baz',
						quux: 'quux',
					};

					return { types };
				},
			});

			await topics.events.init();

			assert(topics.events._types.foo);
			assert.deepStrictEqual(topics.events._types.foo, {
				icon: 'bar',
				text: 'baz',
				quux: 'quux',
			});
		});
	});

	describe('.log()', () => {
		it('should log and return a set of new events in the topic', async () => {
			const events = await topics.events.log(topic.topicData.tid, {
				type: 'foo',
			});

			assert(events);
			assert(Array.isArray(events));
			events.forEach((event) => {
				assert(['id', 'icon', 'text', 'timestamp', 'timestampISO', 'type', 'quux'].every(key => event.hasOwnProperty(key)));
			});
		});
	});

	describe('.get()', () => {
		it('should get a topic\'s events', async () => {
			const events = await topics.events.get(topic.topicData.tid);

			assert(events);
			assert(Array.isArray(events));
			assert.strictEqual(events.length, 1);
			events.forEach((event) => {
				assert(['id', 'icon', 'text', 'timestamp', 'timestampISO', 'type', 'quux'].every(key => event.hasOwnProperty(key)));
			});
		});
	});

	describe('.purge()', () => {
		let eventIds;

		before(async () => {
			const events = await topics.events.get(topic.topicData.tid);
			eventIds = events.map(event => event.id);
		});

		it('should purge topic\'s events from the database', async () => {
			await topics.events.purge(topic.topicData.tid);

			const keys = [`topic:${topic.topicData.tid}:events`];
			keys.push(...eventIds.map(id => `topicEvent:${id}`));

			const exists = await Promise.all(keys.map(key => db.exists(key)));
			assert(exists.every(exists => !exists));
		});
	});

	describe('backlinks', () => {
		let target;
		let otherTarget;
		let source;
		let originalSetting;
		const backlinkEvents = async tid => (await topics.events.get(tid, fooUid)).filter(event => event.type === 'backlink');

		before(async () => {
			const { topicBacklinks } = meta.config;
			originalSetting = topicBacklinks;
			meta.config.topicBacklinks = 1;
			const { cid } = topic.topicData;
			target = await topics.post({ uid: fooUid, cid, title: 'Backlink target', content: 'Target post content' });
			otherTarget = await topics.post({ uid: fooUid, cid, title: 'Other backlink target', content: 'Other target content' });
			source = await topics.post({ uid: fooUid, cid, title: 'Backlink source', content: 'Source post content' });
		});

		after(() => {
			meta.config.topicBacklinks = originalSetting;
		});

		it('should reject invalid post data', async () => {
			await assert.rejects(topics.syncBacklinks(), { message: '[[error:invalid-data]]' });
			await assert.rejects(topics.syncBacklinks({ pid: source.postData.pid }), { message: '[[error:invalid-data]]' });
		});

		it('should add one backlink for repeated site and bare topic links, ignoring self and missing topics', async () => {
			const { pid, uid, tid } = source.postData;
			const targetTid = target.topicData.tid;
			const content = [
				`${nconf.get('url')}/topic/${targetTid}/backlink-target`,
				`/topic/${targetTid}`,
				`/topic/${tid}/self`,
				'/topic/99999999/missing',
			].join(' ');
			const postData = { pid, uid, tid, content };
			const before = Date.now();

			assert.strictEqual(await topics.syncBacklinks(postData), 1);
			assert.deepStrictEqual(await db.getSortedSetRange(`pid:${pid}:backlinks`, 0, -1), [String(targetTid)]);
			assert((await db.sortedSetScore(`pid:${pid}:backlinks`, targetTid)) >= before);

			const events = await backlinkEvents(targetTid);
			assert.strictEqual(events.length, 1);
			assert.strictEqual(events[0].text, '[[topic:backlink]]');
			assert.strictEqual(events[0].href, `/post/${pid}`);
			assert.strictEqual(events[0].uid, uid);

			assert.strictEqual(await topics.syncBacklinks(postData), 0);
			assert.strictEqual((await backlinkEvents(targetTid)).length, 1);
		});

		it('should hide backlink events when topicBacklinks is disabled', async () => {
			meta.config.topicBacklinks = 0;
			try {
				assert.deepStrictEqual(await backlinkEvents(target.topicData.tid), []);
			} finally {
				meta.config.topicBacklinks = 1;
			}
			assert.strictEqual((await backlinkEvents(target.topicData.tid)).length, 1);
		});

		it('should remove stale backlinks and add newly referenced topics', async () => {
			const { pid, uid, tid } = source.postData;
			const otherTid = otherTarget.topicData.tid;
			assert.strictEqual(await topics.syncBacklinks({ pid, uid, tid, content: `See /topic/${otherTid}` }), 2);
			assert.deepStrictEqual(await db.getSortedSetRange(`pid:${pid}:backlinks`, 0, -1), [String(otherTid)]);
			assert.deepStrictEqual(await backlinkEvents(target.topicData.tid), []);
			assert.strictEqual((await backlinkEvents(otherTid))[0].href, `/post/${pid}`);

			assert.strictEqual(await topics.syncBacklinks({ pid, uid, tid, content: 'No topic links remain' }), 1);
			assert.deepStrictEqual(await db.getSortedSetRange(`pid:${pid}:backlinks`, 0, -1), []);
			assert.deepStrictEqual(await backlinkEvents(otherTid), []);
		});

		it('should synchronize links in the initial post when creating a topic', async () => {
			const result = await topics.post({
				uid: fooUid,
				cid: topic.topicData.cid,
				title: 'Topic linking to another topic',
				content: `See ${nconf.get('url')}/topic/${target.topicData.tid}/backlink-target`,
			});
			const { pid } = result.postData;
			assert.deepStrictEqual(await db.getSortedSetRange(`pid:${pid}:backlinks`, 0, -1), [String(target.topicData.tid)]);
			assert((await backlinkEvents(target.topicData.tid)).some(event => event.href === `/post/${pid}` && event.uid === fooUid));
		});

		it('should synchronize backlinks when editing a post', async () => {
			const { pid } = source.postData;
			const title = 'Backlink source';
			await posts.edit({ pid, uid: fooUid, title, tags: [], content: `See /topic/${otherTarget.topicData.tid}` });
			assert.deepStrictEqual(await db.getSortedSetRange(`pid:${pid}:backlinks`, 0, -1), [String(otherTarget.topicData.tid)]);
			assert((await backlinkEvents(otherTarget.topicData.tid)).some(event => event.href === `/post/${pid}`));

			await posts.edit({ pid, uid: fooUid, title, tags: [], content: 'No topic links remain' });
			assert.deepStrictEqual(await db.getSortedSetRange(`pid:${pid}:backlinks`, 0, -1), []);
			assert.deepStrictEqual(await backlinkEvents(otherTarget.topicData.tid), []);
		});
	});
});

